import React from 'react';

function Playlist({ songs, onSongSelect, currentSong, onToggleSelect, selectedSongs }) {
  return (
    <div className="playlist">
      <h2>Playlist</h2>
      <ul>
        {songs.map((song) => (
          <li
            key={song.id}
            className={currentSong.id === song.id ? 'active' : ''}
          >
            <input
              type="checkbox"
              checked={selectedSongs.includes(song.id)}
              onChange={() => onToggleSelect(song.id)}
            />
            <img src={song.cover} alt={song.album} className="cover" />
            <div className="song-info" onClick={() => onSongSelect(song)}>
              <span className="title">{song.title}</span>
              <span className="artist">{song.artist}</span>
            </div>
            <span className="duration">{song.duration}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default Playlist;
